// XDP (eXpress Data Path) - 最早的网络入口点
SEC("xdp")
int xdp_drop_icmp(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_PASS;

    if (eth->h_proto != bpf_htons(ETH_P_IP))
        return XDP_PASS;

    struct iphdr *iph = (void *)(eth + 1);
    if ((void *)(iph + 1) > data_end)
        return XDP_PASS;

    // 丢弃 ICMP 包
    if (iph->protocol == IPPROTO_ICMP)
        return XDP_DROP;

    return XDP_PASS;
}

// TC (Traffic Control) - 流量控制层
SEC("tc")
int tc_filter_egress(struct __sk_buff *skb) {
    void *data = (void *)(long)skb->data;
    void *data_end = (void *)(long)skb->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return TC_ACT_OK;

    // 标记特定流量
    if (eth->h_proto == bpf_htons(ETH_P_IP)) {
        struct iphdr *iph = (void *)(eth + 1);
        if ((void *)(iph + 1) > data_end)
            return TC_ACT_OK;

        // 设置 DSCP 标记
        iph->tos = (iph->tos & 0x03) | (0x2E << 2);
    }

    return TC_ACT_OK;
}

// kprobe - 动态跟踪内核函数
SEC("kprobe/do_sys_openat2")
int trace_open(struct pt_regs *ctx) {
    u64 pid = bpf_get_current_pid_tgid() >> 32;
    u64 ts = bpf_ktime_get_ns();

    // 记录每次 open 系统调用
    struct event evt = {
        .pid = pid,
        .ts = ts,
    };
    bpf_get_current_comm(&evt.comm, sizeof(evt.comm));

    bpf_map_update_elem(&events, &pid, &evt, BPF_ANY);
    return 0;
}

// tracepoint - 静态内核跟踪点
SEC("tracepoint/syscalls/sys_enter_write")
int trace_write(struct trace_event_raw_sys_enter *ctx) {
    u64 pid = bpf_get_current_pid_tgid() >> 32;
    int fd = ctx->args[0];
    size_t count = ctx->args[2];

    struct write_event evt = {
        .pid = pid,
        .fd = fd,
        .count = count,
    };
    bpf_perf_event_output(ctx, &events, BPF_F_CURRENT_CPU,
                          &evt, sizeof(evt));
    return 0;
}

// uprobe - 用户态函数跟踪
SEC("uprobe/libc.so.6:malloc")
int trace_malloc(struct pt_regs *ctx) {
    u64 pid = bpf_get_current_pid_tgid() >> 32;
    size_t size = PT_REGS_PARM1(ctx);

    bpf_printk("malloc(%lu) pid=%lu", size, pid);
    return 0;
}

